<# Pure request derivation, archived-function loading and path checks. No writes or device calls. #>
[CmdletBinding()]param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$script:checks=0
function Check([bool]$Value,[string]$Name){if(-not$Value){throw $Name};$script:checks++}
function Reject([scriptblock]$Body,[string]$Name){$failed=$false;try{&$Body|Out-Null}catch{$failed=$true};Check $failed $Name}
function Clone($Value){$Value|ConvertTo-Json -Depth 32|ConvertFrom-Json}
$workspace=Split-Path -Parent $PSScriptRoot;$path=Join-Path $workspace 'scripts\New-LabNativeReconstructRequest.ps1';$tokens=$null;$errors=$null
$ast=[Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors);Check ($errors.Count-eq0) 'generator parses'
foreach($f in $ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)){. ([scriptblock]::Create($f.Extent.Text))}
foreach($spec in @(
 @('lab\guest\Invoke-GuestNativeProbe.ps1',@('Assert-NativeProbeFields','Assert-NativeProbeGuid','Assert-NativeProbeBinding','Assert-NativeProbeRequest','Assert-NativeProbeSame','Assert-NativeProbeResult')),
 @('scripts\Invoke-LabRetainedNativeProbe.ps1',@('Assert-RetainedProbeBoolean','Assert-RetainedProbePreparation')),
 @('lab\guest\Restore-GuestShadowAttachment.ps1',@('Assert-AttachmentBoolean','Assert-AttachmentGuid','Assert-AttachmentPreparation'))
)){Import-NGRGuards ([pscustomobject]@{bytes=[IO.File]::ReadAllBytes((Join-Path $workspace $spec[0]))}) $spec[1];$script:checks++}
function G([int]$Id){'{0:d8}-1111-2222-aabb-123456789abc'-f$Id}
function V([int]$Id){'\\?\Volume{'+(G $Id)+'}\'}
function Identity([int]$Id){[pscustomobject]@{disk_guid=(G $Id);partition_guid=(G ($Id+1));partition_number=2;disk_bytes=64GB;partition_offset=16MB;partition_bytes=52GB;logical_sector_bytes=512;physical_sector_bytes=4096}}
function Binding([int]$Number,[int]$Id){[pscustomobject]@{disk_number=$Number;volume_guid=(G ($Id+2));identity=(Identity $Id)}}
$id='a'*32;$probe=[pscustomobject]@{schema_version=1;experiment_id=$id;fixture_evidence_sha256=('5'*64);target=(Binding 1 10);shadow=(Binding 3 20);retained_offset=8GB;source_retained_sha256=('3'*64);shadow_retained_sha256=('4'*64)}
function Snapshot($Binding,[int]$Attrs){[pscustomobject]@{binding=(Clone $Binding);disk_attributes=$Attrs;device=(@(0)*12);length=(@(0)*8);alignment=(@(0)*28);layout=(@(0)*336)}}
function Report([bool]$Reopen){[pscustomobject]@{schema_version=1;kind='native-partition-isolation-probe';request=(Clone $probe);reopen=$Reopen;success=$true;phase='complete-disks-remain-offline';error=$null;target_snapshot=(Snapshot $probe.target 1);shadow_snapshot=(Snapshot $probe.shadow 3);target_retained_sha256=$probe.source_retained_sha256;shadow_retained_sha256=$probe.shadow_retained_sha256;target_partition_sha256=$(if($Reopen){'1'*64}else{$null});shadow_partition_sha256=$(if($Reopen){'2'*64}else{$null});target_flush_succeeded=$true;target_bytes_read=$(if($Reopen){52GB+65536}else{65536});shadow_bytes_read=$(if($Reopen){52GB+65536}else{65536});payload_write_requests_issued=$false;conversion_qualified=$false;events=@([pscustomobject]@{operation='get-disk-attributes';control_code=0x700f0;input=@();succeeded=$true;native_error=$null;output=@(16)})}}
$sources=@(foreach($name in @('Invoke-GuestNativeProbe.ps1','Invoke-LabRetainedNativeProbe.ps1','Restore-GuestShadowAttachment.ps1','NativeShadowDisk.cs','NativeShadowReadOnlyAttachment.cs','NativeMountBoundary.cs','Lab.psm1','lab-native-probe.exe')){[pscustomobject]@{name=$name;sha256=('6'*64);length=100;archive='Z:\ignored\path'}})
$hostProof=[pscustomobject]@{schemaVersion=1;kind='retained-native-probe-host';runId=$id;status='native-isolation-and-restart-verified';phase='complete';vmId='eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c';baselineId='eda059b3-6d50-46bb-bdf4-018b99b5b34f';firstProbeId=('b'*32);secondProbeId=('c'*32);preparedCheckpointId=(G 40);preparedCheckpointName=('retained-prepared-'+$id);isolatedCheckpointId=(G 41);isolatedCheckpointName=('retained-isolated-'+$id);quiescentCheckpointId=(G 42);quiescentCheckpointName=('retained-quiescent-'+$id);inspectionExported=$true;firstNativeExported=$true;secondNativeExported=$true;baselineRestored=$true;memoryRestored=$true;payloadWriteRequestsIssued=$false;conversionQualified=$false;transportCompletionUnknown=$false;guestOperationUnknown=$false;sessionPreserved=$false;preparationResultSha256=('7'*64);inspectionEvidenceSha256=('5'*64);requestSha256=('8'*64);firstNativeReportSha256=('9'*64);secondNativeReportSha256=('a'*64);targetPartitionSha256=('1'*64);shadowPartitionSha256=('2'*64);reviewedSourcesSha256=('b'*64);sourceHashes=$sources}
$prepared=[pscustomobject]@{schemaVersion=1;kind='retained-preparation-host';status='retained-pair-prepared-awaiting-raw-proof';phase='complete';runId=$id;observationId=('d'*32);vmId=$hostProof.vmId;baselineId=$hostProof.baselineId;outcomeCheckpointName=$hostProof.preparedCheckpointName;outcomeCheckpointId=$hostProof.preparedCheckpointId;sourceExported=$true;shadowExported=$true;pairExported=$true;cleanShutdown=$true;outcomeCheckpointCreated=$true;baselineRestored=$true;memoryRestored=$true;commandCompletionUnknown=$false;physicalMappingVerified=$false;cleanRemountVerified=$false;conversionQualified=$false;sourceEvidenceSha256=('c'*64);shadowEvidenceSha256=('d'*64);pairEvidenceSha256=('e'*64);reviewedSourcesSha256=('f'*64);retainedInterval=[pscustomobject]@{offset=8GB;length=65536;candidateLcn=2097152;sourceSha256=('3'*64);shadowSha256=('4'*64)}}
$source=[pscustomobject]@{schemaVersion=1;kind='retained-ntfs-source-platform';status='ntfs-source-prepared';phase='complete';runId=$id;target=[pscustomobject]@{guest=[pscustomobject]@{uniqueId='60022480D091C4251B5FFD619706C2B5';sizeBytes=64GB}};partition=[pscustomobject]@{number=2;offset=16MB;length=52GB;logicalSectorSize=512;physicalSectorSize=4096;diskGuid=(G 10);guid=(G 11)};volume=[pscustomobject]@{guid=(V 12);filesystem='NTFS';allocationUnitSize=4096};operationCompletionKnown=$true;conversionQualified=$false}
$shadow=[pscustomobject]@{schemaVersion=1;kind='guest-local-shadow-platform';status='shadow-platform-prepared';runId=$id;nativeSourceSha256=('6'*64);backingPath=('J:\ntfs2refs-shadow\'+$id+'\shadow.vhdx');attachmentRetained=$true;handleCloseSucceeded=$true;nativeOperationCompletionKnown=$true;privilegeRestored=$true;sourceTargetWriteRequestsIssued=$false;payloadCopied=$false;conversionQualified=$false;bootQualified=$false;journalIdentity=[pscustomobject]@{uniqueId='600224806AAC261F021F249596F332FC';sizeBytes=8GB;role='journal'};journal=[pscustomobject]@{diskNumber=2;partitionNumber=2;offset=16MB;length=(8GB-32MB);letter='J';filesystem='NTFS';allocationUnitSize=4096;diskGuid=(G 30);partitionGuid=(G 31);volumeGuid=(V 32)};shadow=[pscustomobject]@{physicalPath='\\.\PhysicalDrive3';diskNumber=3;diskUniqueId='independently-enrolled-shadow';partitionNumber=2;offset=16MB;length=52GB;logicalSectorSize=512;physicalSectorSize=4096;letter='S';filesystem='ReFS';allocationUnitSize=4096;diskGuid=(G 20);partitionGuid=(G 21);volumeGuid=(V 22)};vhdIdentifier=(G 50);vhdIdentityQueryVersion=14;vhdContentGenerationQueryVersion=2;finalVhd=[pscustomobject]@{identifier=(G 51);virtualDiskId=(G 50);identifierQueryVersion=2;virtualDiskIdQueryVersion=14;identifierSemantics='vhdx-content-generation';virtualBytes=64GB;blockBytes=2MB;logicalSectorBytes=512;physicalSectorBytes=4096;providerSubtype=3;physicalPath='\\.\PhysicalDrive3'}}
$hostProof.isolatedCheckpointName='retained-isolated-'+$hostProof.firstProbeId;$hostProof.quiescentCheckpointName='retained-quiescent-'+$hostProof.secondProbeId
$hostProof|Add-Member shadowProtectionProfile 'provider-readonly-explicit-exclusion';$hostProof|Add-Member shadowPersistenceQualified $false;$hostProof|Add-Member excludedAttachmentSha256 ('c'*64)
$first=Report $false;$second=Report $true
function Derive($H=$hostProof,$P=$probe,$A=$first,$B=$second,$Prep=$prepared,$S=$source,$Sh=$shadow){New-NGRRequest $H $P $A $B $Prep $S $Sh}
$request=Derive;Check ($request.experiment_id-ceq$id) 'derived run';Check ($request.comparison.source_sha256-ceq('1'*64)-and$request.comparison.shadow_sha256-ceq('2'*64)) 'whole hashes from second report'
Import-NGRGuards ([pscustomobject]@{bytes=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestNativeReconstruct.ps1'))}) @('Assert-NRFields','Assert-NRBool','Assert-NRNumber','Assert-NRHash','Assert-NRGuid','Assert-NRPartition','Assert-NRRequest')
Assert-NRRequest $request $id;$script:checks++;Assert-NRRequest (Clone $request) $id;$script:checks++
Check ($request.comparison.sector_size-eq4096-and$request.comparison.expected_length-eq52GB-and$request.comparison.max_change_bytes-eq256MB-and$request.comparison.max_ranges-eq65536-and$request.max_journal_bytes-eq768MB) 'fixed bounds'
Check ($request.comparison.retained_ranges.Count-eq1-and$request.comparison.retained_ranges[0].offset-eq8GB-and$request.comparison.retained_ranges[0].length-eq65536) 'retained exact interval'
Check ($request.journal.disk_number-eq2-and$request.journal.identity.partition_bytes-eq(8GB-32MB)-and$request.journal.volume_guid-ceq(G 32)) 'journal independent identity'
foreach($change in @({param($x)$x.status='failed-preserved'},{param($x)$x.phase='native-isolation'},{param($x)$x.runId='f'*32},{param($x)$x.firstProbeId=$x.secondProbeId},{param($x)$x.vmId=G 98},{param($x)$x.baselineId=G 99},{param($x)$x.quiescentCheckpointId=$x.isolatedCheckpointId},{param($x)$x.quiescentCheckpointName='wrong'},{param($x)$x.targetPartitionSha256='f'*64},{param($x)$x.inspectionEvidenceSha256='0'*64},{param($x)$x.preparedCheckpointId=G 44},{param($x)$x.sourceHashes=@($x.sourceHashes[0])},{param($x)$x.schemaVersion='1'})){$x=Clone $hostProof;&$change $x;Reject {Derive -H $x} 'bad host proof'}
foreach($name in @('inspectionExported','firstNativeExported','secondNativeExported','baselineRestored','memoryRestored','payloadWriteRequestsIssued','conversionQualified','transportCompletionUnknown','guestOperationUnknown','sessionPreserved')){foreach($value in @('false',$null,(-not[bool]$hostProof.$name))){$x=Clone $hostProof;$x.$name=$value;Reject {Derive -H $x} ('bad explicit '+$name)}}
foreach($change in @({param($x)$x.success=$false},{param($x)$x.target_snapshot.disk_attributes=0},{param($x)$x.shadow_snapshot.disk_attributes=1},{param($x)$x.target_partition_sha256=$null},{param($x)$x.target_bytes_read=65536},{param($x)$x.payload_write_requests_issued=$true},{param($x)$x.target_retained_sha256='f'*64},{param($x)$x.request.target.identity.partition_guid=G 97})){$x=Clone $second;&$change $x;Reject {Derive -B $x} 'invalid restart report'}
$x=Clone $first;$x.reopen=$true;Reject {Derive -A $x} 'first cannot be reopen'
foreach($name in @('isolated','quiescent')){$x=Clone $hostProof;$x.($name+'CheckpointName')='retained-'+$name+'-'+$x.runId;Reject {Derive -H $x} 'legacy run-only outcome cannot collide with new attempt'}
foreach($change in @({param($x)$x.shadowProtectionProfile='persistent-attributes'},{param($x)$x.shadowPersistenceQualified=$true},{param($x)$x.excludedAttachmentSha256='invalid'},{param($x)$x.sourceHashes[0].name='unreviewed.cs'})){$x=Clone $hostProof;&$change $x;Reject {Derive -H $x} 'unqualified shadow protection'}
$x=Clone $probe;$x.retained_offset='8589934592';Reject {Derive -P $x} 'string offset refused'
$x=Clone $probe;$x.target.identity.logical_sector_bytes='512';Reject {Derive -P $x} 'string geometry refused'
$x=Clone $prepared;$x.retainedInterval.offset+=4096;$x.retainedInterval.candidateLcn++;Reject {Derive -Prep $x} 'prepared retained disagreement'
$x=Clone $prepared;$x.commandCompletionUnknown=$true;Reject {Derive -Prep $x} 'unknown preparation'
foreach($change in @({param($x)$x.journal.diskGuid=G 10},{param($x)$x.journal.partitionGuid=G 11},{param($x)$x.journal.volumeGuid=V 12},{param($x)$x.journalIdentity.uniqueId='other'},{param($x)$x.journal.length=8GB},{param($x)$x.nativeSourceSha256='7'*64},{param($x)$x.privilegeRestored=$false},{param($x)$x.shadow.partitionGuid=G 97})){$x=Clone $shadow;&$change $x;Reject {Derive -Sh $x} 'bad journal/shadow evidence'}
$x=Clone $source;$x.partition.diskGuid=G 97;Reject {Derive -S $x} 'source GPT differs'
$root='D:\code\ntfs2refs\.lab';Check ((Assert-NGRPath ($root+'\case\request.json') $root)-ceq($root+'\case\request.json')) 'safe path'
foreach($p in @('relative.json','C:\outside.json','D:\code\ntfs2refs\.lab-evil\a.json',($root+'\..\a.json'),($root+'\x\..\a.json'),($root+'\x\a.json:stream'),($root+'\x\a.'),($root+'\x\a '),($root+'\NUL.json'),($root+'\x\\a.json'),'\\.\PhysicalDrive1',($root+'/x/a.json'))){Reject {Assert-NGRPath $p $root} 'unsafe path'}
Reject {Import-NGRGuards ([pscustomobject]@{bytes=[Text.Encoding]::UTF8.GetBytes('function Other {}')}) @('Required')} 'missing archived named function'
Reject {Import-NGRGuards ([pscustomobject]@{bytes=[Text.Encoding]::UTF8.GetBytes('function X {}; function X {}')}) @('X')} 'ambiguous archived function'
Check ($null-ne(Convert-NGRJson ([pscustomobject]@{bytes=[byte[]]@(239,187,191,123,125)}))) 'one leading UTF8 BOM accepted for parsing'
Reject {Convert-NGRJson ([pscustomobject]@{bytes=[byte[]]@(239,187,191,239,187,191,123,125)})} 'duplicate leading BOM refused'
Reject {Convert-NGRJson ([pscustomobject]@{bytes=[byte[]]@(255)})} 'invalid UTF8 refused'
Check ((Get-NGRSha ([Text.Encoding]::UTF8.GetBytes('abc')))-ceq'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad') 'SHA known vector'
$commands=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.CommandAst]},$true)|ForEach-Object{$_.GetCommandName()}|Where-Object{$_})
Check (@($commands|Where-Object{$_-match '\A(?:Get-Disk|Get-Partition|Get-Volume|Set-Disk|Start-Process|Invoke-Command|.*-VM|Add-Type|Remove-Item|Move-Item|Copy-Item|Import-Module)\z'}).Count-eq0) 'no native/VM/process/mutating command path'
$text=[IO.File]::ReadAllText($path);Check ($text.Contains('[IO.FileMode]::CreateNew')-and$text.Contains('.Flush($true)')) 'durable create-new writer'
Write-Output ('Native request generator: '+$script:checks+' pure/schema/path/archive checks passed; no VM, device or file writes.')
